 (a) curve y=3-x^2/12    → TubeGeometry (r=0.045) teal #17B3BC
 (a) all n strips        → LineSegments outlines, light grey
 (a) strip R_k           → PlaneGeometry pale teal #AFD9D4 + LineLoop grey outline
 (a) ticks x_{k-1}, x_k  → LineSegments below axis, black
 (b) solid of revolution → LatheGeometry(profile of f), MeshLambert grey a=0.28, depthWrite off
 (b) rims/silhouette     → Line circles (top rim, base) + 2 vertical Lines, #5A5A5A
 (b) partition rings     → merged LineSegments circles at each x_i on the top surface
 (b) shell S_k           → LatheGeometry of the rectangle cross-section, grey a=0.75
 (b) shell rims          → 4 Line circles (inner/outer, top/bottom), #5A5A5A
 (b) teal face of R_k    → PlaneGeometry z=0 on +X, pale teal, polygonOffset
 (b) teal profile curve  → TubeGeometry on the top surface, teal
 (b) x-axis, y-axis      → Cylinder shaft + Cone head, black
 highlights              → orange Arrow (r), Arrow+bar (h), Torus ring (2πr), Ring+arrow (Δx)
─────────────────────────────────────────────────────────────────────────────*/

const S = 0.45, AX = -4.10, BX = 1.50;      // panel scale + world offsets
const Bo = 4.0;                              // outer radius / right end of region
const f = x => 3 - x * x / 12;
const EXACT = 117.286;

const TEAL = 0x17B3BC, PALE = 0xAFD9D4, EDGE = 0x5A5A5A, LIGHT = 0xB4B4B4;
const GSOLID = 0xCFCFCF, GSHELL = 0xA6A6A6, ORANGE = 0xE8820C, BLACK = 0x000000;
const V3 = THREE.Vector3;

scene.add(new THREE.HemisphereLight(0xffffff, 0x999999, 1.05));
const _dl = new THREE.DirectionalLight(0xffffff, 0.55); _dl.position.set(3, 6, 8); scene.add(_dl);

/* ── helpers ─────────────────────────────────────────────────────────────── */
function mkArrow(from, to, color, shaftR, headR, headL) {
  const g = new THREE.Group();
  const dir = new V3().subVectors(to, from), len = dir.length();
  if (len < 1e-6) return g;
  const n = dir.clone().normalize();
  const sl = Math.max(len - headL, 1e-3);
  const m = new THREE.MeshBasicMaterial({ color });
  const cyl = new THREE.Mesh(new THREE.CylinderGeometry(shaftR, shaftR, sl, 12), m);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(headR, headL, 18), m);
  const q = new THREE.Quaternion().setFromUnitVectors(new V3(0, 1, 0), n);
  cyl.quaternion.copy(q); cone.quaternion.copy(q);
  cyl.position.copy(from).addScaledVector(n, sl / 2);
  cone.position.copy(from).addScaledVector(n, sl + headL / 2);
  g.add(cyl, cone); g.renderOrder = 4;
  return g;
}
function mkLine(pts, color, opacity) {
  const mat = new THREE.LineBasicMaterial({ color, transparent: (opacity ?? 1) < 1, opacity: opacity ?? 1 });
  const l = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), mat);
  l.renderOrder = 4; return l;
}
function mkSegs(arr, color, opacity) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3));
  const l = new THREE.LineSegments(g, new THREE.LineBasicMaterial({ color, transparent: (opacity ?? 1) < 1, opacity: opacity ?? 1 }));
  l.renderOrder = 4; return l;
}
function ringPts(r, y, seg) {
  const p = []; seg = seg || 96;
  for (let i = 0; i <= seg; i++) { const a = i / seg * Math.PI * 2; p.push(new V3(r * Math.cos(a), y, r * Math.sin(a))); }
  return p;
}
function mkTube(pts, r, color) {
  const c = new THREE.CatmullRomCurve3(pts);
  const m = new THREE.Mesh(new THREE.TubeGeometry(c, Math.max(24, pts.length * 2), r, 10, false),
    new THREE.MeshBasicMaterial({ color }));
  m.renderOrder = 5; return m;
}
function clearGroup(g) {
  for (let i = g.children.length - 1; i >= 0; i--) {
    const c = g.children[i];
    c.traverse(o => {
      o.geometry?.dispose?.();
      if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.()); else o.material?.dispose?.();
    });
    g.remove(c);
  }
}

/* ── groups ──────────────────────────────────────────────────────────────── */
const gA = new THREE.Group(); gA.position.set(AX, 0, 0); gA.scale.setScalar(S);
const gB = new THREE.Group(); gB.position.set(BX, 0, 0); gB.scale.setScalar(S);
const wA = (x, y, z) => new V3(AX + x * S, y * S, (z || 0) * S);
