  for (const L of labelReg) {
    const vis = (L.panel === 'a' ? shownA() : shownB()) && (!L.show || L.show());
    if (vis) L.e.pos.copy(L.posFn()); else L.e.pos.set(1e6, 1e6, 1e6);
  }
}

/* ── UI wiring ───────────────────────────────────────────────────────────── */
const $ = id => document.getElementById(id);
const viewBtns = { a: $('vA'), b: $('vB'), both: $('vBoth') };
const facBtns = { off: $('fOff'), r: $('fR'), h: $('fH'), c: $('fC'), t: $('fT') };
const kSl = $('kIndex'), nSl = $('nStrips');

function frameCamera() {
  const tA = [AX + 2.30 * S, 1.60 * S, 0], tB = [BX, 1.60 * S, 0];
  if (view === 'a') setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 0.6, z: 75 }, heightFraction: 0.66, target: tA });
