  else setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 1.5, z: 75 }, heightFraction: 0.60, target: [(tA[0] + tB[0]) / 2, 1.6 * S, 0] });
}
function applyView() {
  shownA() ? scene.add(gA) : scene.remove(gA);
  shownB() ? scene.add(gB) : scene.remove(gB);
