    '&Delta;<i>x</i> = <i>b</i>/<i>n</i> = ' + dx.toFixed(3) + '<br>' +
    '&Delta;<i>V</i><sub>k</sub> = 2&pi;<i>r h</i>&Delta;<i>x</i> = <b>' + dV.toFixed(3) + '</b><br>' +
    '&Sigma;&Delta;<i>V</i><sub>k</sub> = ' + sum.toFixed(3) + ' &nbsp;(exact ' + EXACT.toFixed(2) + ')';
  $('kOut').textContent = k; $('nOut').textContent = n;
}
function refresh() {
  if (k > n) k = n; if (k < 1) k = 1;
