  buildStrips(); buildRings(); buildShell(); buildHighlights();
  for (const key in facBtns) facBtns[key].classList.toggle('active', factor === key);
  updateReadout(); updateLabels();
}
viewBtns.a.onclick = () => { view = 'a'; applyView(); };
viewBtns.b.onclick = () => { view = 'b'; applyView(); };
viewBtns.both.onclick = () => { view = 'both'; applyView(); };
kSl.oninput = () => { k = +kSl.value; refresh(); };
nSl.oninput = () => { n = +nSl.value; refresh(); };
for (const key in facBtns) facBtns[key].onclick = (kk => () => { factor = kk; refresh(); })(key);

/* ── guided demo ─────────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'One approximating rectangle', n: 'In the xy-plane the region under y = f(x) is sliced into n vertical strips; the k-th strip is approximated by the rectangle R\u2096 from x\u2096₋₁ to x\u2096 with height f(x\u2096*).', s: { view: 'a', n: 8, k: 5, factor: 'off' } },
  { t: 'Revolve it about the y-axis', n: 'Sweeping R\u2096 a full turn about the y-axis traces the cylindrical shell S\u2096: a tube of inner radius x\u2096₋₁ and outer radius x\u2096 nested inside the solid of revolution.', s: { view: 'b', n: 8, k: 5, factor: 'off' } },
  { t: 'Radius and height', n: 'The shell\u2019s radius r\u2096 is the distance from the y-axis to the strip; its height h\u2096 is the value f(x\u2096*) that capped the rectangle.', s: { view: 'b', n: 8, k: 5, factor: 'r' } },
  { t: 'Unroll the shell', n: 'Cut and flatten the tube: it becomes a thin slab of length 2\u03C0r\u2096, height h\u2096 and thickness \u0394x, so \u0394V\u2096 \u2248 2\u03C0 r\u2096 h\u2096 \u0394x.', s: { view: 'b', n: 8, k: 5, factor: 'c' } },
  { t: 'Move outward through the strips', n: 'Stepping k outward shows the radius growing while the height shrinks along the decreasing curve \u2014 each nested tube contributes a different amount.', s: { view: 'both', n: 8, k: 8, factor: 'off' } },
  { t: 'Let n grow', n: 'With many thin shells the nested tubes fill the solid and \u03A3 2\u03C0r\u2096h\u2096\u0394x approaches \u222B\u2080\u1D47 2\u03C0x f(x) dx = 117.29.', s: { view: 'both', n: 32, k: 20, factor: 't' } }
];
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx], prevView = view;
  view = st.s.view; n = st.s.n ?? n; k = st.s.k; factor = st.s.factor;
  $('stepTitle').textContent = (stepIdx + 1) + '/' + STEPS.length + '  ' + st.t;
  $('stepNarr').textContent = st.n;
  refresh();
  if (prevView !== view) applyView(); else { updateLabels(); frameCamera(); }
  for (const key in viewBtns) viewBtns[key].classList.toggle('active', view === key);
}
$('nextStep').onclick = () => goToStep(stepIdx + 1);
$('prevStep').onclick = () => goToStep(stepIdx - 1);

/* ── init ────────────────────────────────────────────────────────────────── */
refresh();
scene.add(gA);
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 0.6, z: 75 }, heightFraction: 0.66, target: [AX + 2.30 * S, 1.60 * S, 0] });
