  gA.add(mkArrow(p.clone().addScaledVector(tg, -0.17), p.clone().addScaledVector(tg, 0.10), BLACK, 0.014, 0.07, 0.16));
}
const stripsG = new THREE.Group(); gA.add(stripsG);
anchor(gA, -0.2, -2.55); anchor(gA, 4.8, -2.55); anchor(gA, 2.3, -4.05);

/* ── PANEL (b) static ────────────────────────────────────────────────────── */
{
  const prof = [];
  for (let i = 0; i <= 48; i++) { const x = Bo * i / 48; prof.push(new THREE.Vector2(Math.max(x, 1e-4), f(x))); }
  prof.push(new THREE.Vector2(Bo, 0)); prof.push(new THREE.Vector2(1e-4, 0));
  const solid = new THREE.Mesh(new THREE.LatheGeometry(prof, 84),
    new THREE.MeshLambertMaterial({
      color: GSOLID, transparent: true, opacity: 0.28, depthWrite: false, side: THREE.DoubleSide
    }));
  solid.renderOrder = 0;
  registerInteractive(solid, {
    title: 'Solid of revolution',
    tooltip: 'The whole solid (radius b = 4)',
    body: 'Revolving the entire region 0 ≤ x ≤ 4 under y = f(x) = 3 − x²/12 about the y-axis gives this solid. Its exact volume is ∫₀⁴ 2πx(3 − x²/12) dx = 117.29.'
  });
  gB.add(solid);
  gB.add(mkLine(ringPts(Bo, f(Bo)), EDGE));
  gB.add(mkLine(ringPts(Bo, 0), EDGE));
  gB.add(mkSegs([Bo, 0, 0, Bo, f(Bo), 0, -Bo, 0, 0, -Bo, f(Bo), 0], EDGE));
  const cp = [];
  for (let i = 0; i <= 40; i++) { const x = 2.3 + (4.5 - 2.3) * i / 40; cp.push(new V3(x, f(x) + 0.02, 0)); }
  gB.add(mkTube(cp, 0.048, TEAL));
  gB.add(mkArrow(new V3(-5.5, 0, 0), new V3(5.4, 0, 0), BLACK, 0.022, 0.095, 0.30));
  gB.add(mkArrow(new V3(0, 0, 0), new V3(0, 4.15, 0), BLACK, 0.022, 0.095, 0.30));
}
const ringsG = new THREE.Group(); gB.add(ringsG);
const shellG = new THREE.Group(); gB.add(shellG);
const hlG = new THREE.Group(); gB.add(hlG);
anchor(gB, -2.55, -2.55); anchor(gB, 2.55, -2.55); anchor(gB, 0, -4.05);
registerInteractive(shellG, {
  title: 'Cylindrical shell S\u2096',
  tooltip: 'The shell generated by R\u2096',
  body: 'S\u2096 is the tube swept by the rectangle R\u2096 as it turns about the y-axis. Inner radius x\u2096₋₁, outer radius x\u2096, height h\u2096 = f(x\u2096*), so ΔV\u2096 ≈ 2π r\u2096 h\u2096 Δx.'
});

/* ── state ───────────────────────────────────────────────────────────────── */
let view = 'both', n = 8, k = 5, factor = 'off', showAll = false, stepIdx = 0;
const strip = () => {
  const dx = Bo / n, x0 = (k - 1) * dx, x1 = k * dx, rm = (x0 + x1) / 2;
  return { dx, x0, x1, rm, h: f(rm) };
};
const shownA = () => view === 'a' || view === 'both';
const shownB = () => view === 'b' || view === 'both';

/* ── rebuilds ────────────────────────────────────────────────────────────── */
function buildStrips() {
  clearGroup(stripsG);
  const { dx, x0, x1, rm, h } = strip();
  if (showAll) {
    const seg = [];
    for (let i = 1; i <= n; i++) {
      if (i === k) continue;
      const a = (i - 1) * dx, b = i * dx, hi = f((a + b) / 2);
      seg.push(a, 0, 0, a, hi, 0, b, 0, 0, b, hi, 0, a, hi, 0, b, hi, 0);
    }
    if (seg.length) stripsG.add(mkSegs(seg, LIGHT, 0.9));
  }
  const fill = new THREE.Mesh(new THREE.PlaneGeometry(x1 - x0, h),
    new THREE.MeshBasicMaterial({ color: PALE, transparent: true, opacity: 0.92, side: THREE.DoubleSide }));
  fill.position.set(rm, h / 2, 0); fill.renderOrder = 1;
  registerInteractive(fill, {
    title: 'Rectangle R\u2096',
    tooltip: 'Width Δx, height f(x\u2096*)',
    body: 'R\u2096 approximates the k-th vertical strip of the region: base from x\u2096₋₁ to x\u2096 on the x-axis, top at height f(x\u2096*) crossing the curve. Revolving it about the y-axis sweeps out the cylindrical shell S\u2096.'
  });
  stripsG.add(fill);
  stripsG.add(mkSegs([x0, 0, 0, x0, h, 0, x1, 0, 0, x1, h, 0, x0, h, 0, x1, h, 0, x0, 0, 0, x1, 0, 0], 0x6E6E6E));
  stripsG.add(mkSegs([x0, 0, 0, x0, -0.16, 0, x1, 0, 0, x1, -0.16, 0], BLACK));
}
function buildRings() {
  clearGroup(ringsG);
  if (!showAll) return;
  const dx = Bo / n, arr = [];
  for (let i = 1; i < n; i++) {
    const r = i * dx, y = f(r), sg = 64;
    for (let j = 0; j < sg; j++) {
      const a1 = j / sg * 2 * Math.PI, a2 = (j + 1) / sg * 2 * Math.PI;
      arr.push(r * Math.cos(a1), y, r * Math.sin(a1), r * Math.cos(a2), y, r * Math.sin(a2));
    }
  }
  if (arr.length) ringsG.add(mkSegs(arr, LIGHT, 0.5));
}
function buildShell() {
  clearGroup(shellG);
  const { x0, x1, h } = strip();
  const p = [new THREE.Vector2(Math.max(x0, 1e-4), 0), new THREE.Vector2(x1, 0),
  new THREE.Vector2(x1, h), new THREE.Vector2(Math.max(x0, 1e-4), h),
  new THREE.Vector2(Math.max(x0, 1e-4), 0)];
  const m = new THREE.Mesh(new THREE.LatheGeometry(p, 84),
    new THREE.MeshLambertMaterial({
      color: GSHELL, transparent: true, opacity: 0.78, depthWrite: false, side: THREE.DoubleSide
    }));
  m.renderOrder = 1; shellG.add(m);
  shellG.add(mkLine(ringPts(x1, h), EDGE)); shellG.add(mkLine(ringPts(x0, h), EDGE));
  shellG.add(mkLine(ringPts(x1, 0), EDGE)); shellG.add(mkLine(ringPts(x0, 0), EDGE));
  const face = new THREE.Mesh(new THREE.PlaneGeometry(x1 - x0, h),
    new THREE.MeshBasicMaterial({
      color: PALE, transparent: true, opacity: 0.95, side: THREE.DoubleSide,
      polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3, depthWrite: false
    }));
  face.position.set((x0 + x1) / 2, h / 2, 0); face.renderOrder = 3;
  shellG.add(face);
  shellG.add(mkSegs([x0, 0, 0, x0, h, 0, x1, 0, 0, x1, h, 0, x0, h, 0, x1, h, 0], 0x6E6E6E));
  // leader line to the S_k label
  shellG.add(mkLine([new V3(x1, h * 0.55, 0), new V3(x1 + 0.62, h * 0.55, 0)], 0x7A7A7A));
}
function buildHighlights() {
  clearGroup(hlG);
  if (factor === 'off') return;
  const { x0, x1, rm, h } = strip();
  if (factor === 'r') {
    hlG.add(mkArrow(new V3(0, 0.04, 0), new V3(rm, 0.04, 0), ORANGE, 0.035, 0.12, 0.30));
  } else if (factor === 'h') {
    hlG.add(mkArrow(new V3(x1 + 0.12, 0, 0), new V3(x1 + 0.12, h, 0), ORANGE, 0.035, 0.12, 0.30));
    const bar = new THREE.Mesh(new THREE.BoxGeometry(0.06, h, 0.06),
      new THREE.MeshBasicMaterial({ color: ORANGE }));
    bar.position.set(x1, h / 2, 0); bar.renderOrder = 5; hlG.add(bar);
